import assert from 'node:assert/strict';
import { S3Client } from '@aws-sdk/client-s3';
import { encryptArtifact, storeEncryptedArtifact, decryptAndValidateArtifact } from './src/providers/traceArchive.ts';
Object.assign(process.env, {NODE_ENV:'production', ENVIRONMENT:'production', TRACE_ARCHIVE_ENABLED:'1', TRACE_ARCHIVE_BACKEND:'r2', TRACE_ARCHIVE_ENCRYPTION_KEY_B64:Buffer.alloc(32,9).toString('base64'), R2_ACCOUNT_ID:'review-fixture',R2_ACCESS_KEY_ID:'review-fixture',R2_SECRET_ACCESS_KEY:'review-fixture',R2_BUCKET_TRACE_ARCHIVE:'review-fixture'});
const path='db/start.fixture.json.gz.enc';
const a=encryptArtifact(path,Buffer.from('{"generation":"A"}'),'application/json');
const b=encryptArtifact(path,Buffer.from('{"generation":"B"}'),'application/json');
const objects=new Map();const order=[];
let releaseA, markA;
const gate=new Promise(r=>releaseA=r);const firstStored=new Promise(r=>markA=r);
const original=S3Client.prototype.send;
S3Client.prototype.send=async function(command) {
 assert.equal(command.constructor.name,'PutObjectCommand');
 const input=command.input; const body=Buffer.from(input.Body);const key=input.Key;
 const generation=key.endsWith('.meta.json')?(JSON.parse(body.toString()).ciphertext_sha256===a.metadata.ciphertext_sha256?'A':'B'):(body.equals(a.ciphertext)?'A':'B');
 objects.set(key,body);order.push(generation+(key.endsWith('.meta.json')?':metadata':':ciphertext'));
 if(generation==='A'&&!key.endsWith('.meta.json')) {markA();await gate;}
 return {};
};
try {
 const pa=storeEncryptedArtifact({rootAgentId:'review-fixture-root',objectPath:path,...a});await firstStored;
 const rb=await storeEncryptedArtifact({rootAgentId:'review-fixture-root',objectPath:path,...b});releaseA();const ra=await pa;
 const key='trace-archive/review-fixture-root/'+path;
 const ciphertext=objects.get(key);const metadata=JSON.parse(objects.get(key+'.meta.json').toString());
 let rejected;
 try {decryptAndValidateArtifact({ciphertext,metadata});rejected='unexpected success';}catch(e){rejected=e.message;}
 assert.equal(rejected,'Archive ciphertext SHA-256 mismatch');
 assert.ok(ra&&rb);
 console.log(JSON.stringify({producer:'unchanged storeEncryptedArtifact -> putR2',schedule:order,both_publishers_returned_success:true,final_pair:'B ciphertext with A metadata',unchanged_reader_result:rejected,network_requests:0,model_calls:0,scope:'Reproduced producer concurrency class; not proof this schedule caused every historical excluded archive.'}));
} finally {S3Client.prototype.send=original;}
